config.script:
// tcle_cartao — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Gatilho: o TCLE de uma venda ficou completo (todas as assinaturas).
//   1. pega a venda do evento (aceita `subject` ou `payload_safe`); sem venda, sai limpo;
//   2. lê o número da venda (opcional: sem acesso, o cartão sai sem o número);
//   3. mostra um CARTÃO no canto inferior direito da tela de quem tem o papel escolhido
//      (`config.papel_alvo`, padrão medico), com o botão para abrir o TCLE na venda.
//      O cartão é persistente e fica até a pessoa fechar: quem não estava na Central vê ao entrar.
//      Só quem pode ver a venda recebe (requer_permissoes). O mesmo TCLE não duplica (ref por venda).
//
// Sem dado pessoal: o cartão não traz nome do paciente; o ref só leva o id opaco da venda e o papel-alvo
// (o resumo nem isso — só flags).
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var ev = event || {};
var subject = ev.subject || {};
var safe = ev.payload_safe || {};

function txt(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}

var vendaId = txt(subject.venda_id) || txt(safe.venda_id);
if (!vendaId) {
  log('tcle_cartao: evento sem venda — nada a mostrar', 'warning');
  result({ avisado: false, pulado: 'sem_venda' });
  return { ok: true, avisado: false, pulado: 'sem_venda' };
}

var papel = txt(cfg.papel_alvo);
if (!papel || papel.indexOf('{{') === 0) papel = 'medico';

// Número da venda (só para a equipe achar a venda certa). Falha aqui não impede o cartão.
var numero = '';
var venda = unwrap(call('buscar_venda', { venda_id: vendaId }));
if (venda && venda.numero !== undefined && venda.numero !== null) numero = txt(venda.numero);
if (!venda) log('tcle_cartao: não leu a venda (cartão sai sem o número)', 'warning');

var titulo = numero ? ('TCLE assinado · venda ' + numero) : 'TCLE assinado';
var r = call('emitir_snippet', {
  type: 'diretiva_ui',
  kind: 'snippet',
  componente: 'cartao',
  posicao: { ancora: 'inf-dir', dx: 24, dy: 24 },
  estilo: { cor: 'sucesso', icone: 'documento', variante: 'suave', borda: 'fina' },
  titulo: titulo,
  corpo: 'O termo de consentimento foi assinado por todos. Abra a venda para ver e baixar o documento.',
  botoes: [{ label: 'Abrir o TCLE da venda', estilo: 'primary', acao: { tipo: 'link', href: '/venda/' + vendaId + '/tcle' } }],
  duracao: { tipo: 'ate_fechar' },
  persistencia: 'persistente',
  requer_permissoes: ['venda:read'],
  ref: 'tcle-concluido:' + vendaId + ':' + papel,
  alvo: { role: papel }
});

if (!r || !r.ok) {
  log('tcle_cartao: FALHA ao mostrar o cartão (HTTP ' + ((r && r.status_code) || '?') + ')', 'warning');
  result({ avisado: false, acao_bloqueada: true, etapa: 'emitir_snippet', http: (r && r.status_code) || null, com_numero: !!numero });
  return { ok: false, avisado: false, erro: 'emitir_snippet', http: (r && r.status_code) || null };
}

log('tcle_cartao: cartão mostrado ao papel ' + papel);
result({ avisado: true, com_numero: !!numero });
return { ok: true, avisado: true };
